export function shadow(LIMIT) { return LIMIT; }

const LABEL = 'ready';
const ENABLED = true;

/** @returns {string} */
export function label() { if (ENABLED) return LABEL; return 'disabled'; }

/** @typedef {{ $: 'value', value: number } | { $: 'none' }} Choice */

/** @param {number} x @returns {Choice} */
export function makeChoice(x) { return { $: 'value', value: x }; }

/** @param {Choice} choice @returns {number} */
export function readChoice(choice) { switch (choice.$) { case 'value': return choice.value; case 'none': return 0; } }

/** @param {number} [value=99] @returns {number} */
export function add(value = 2) { return value + 1; }

/** @returns {number} */
export function callAdd() { return add(); }

